152	public class OwnerPostcodeAdvice implements RequestBodyAdvice {
153	
154	    /** Region -> inclusive {low, high} 4-digit postcode range. */
155	    private static final Map<String, int[]> REGION_RANGE =
156	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
